import { test } from '@playwright/test';
import { prepareReadOnly, openCalculator, fillInputs, expectResult, SET1, DEVICES, CalcInput } from './calculator.helpers';

test.use({ serviceWorkers: 'block' });

/** Одно поле меняется, остальные — набор 1; ожидаемые результаты по формулам #d45b2a/#80ff63. */
const CASES: { name: CalcInput; value: string; expect: Record<string, string> }[] = [
  { name: 'purchasePrice', value: '510000', expect: { 'סך השקעה ראשונית': '610,000 ₪', 'הון עצמי נדרש': '410,000 ₪' } },
  { name: 'setupCosts', value: '60000', expect: { 'סך השקעה ראשונית': '610,000 ₪', 'הון עצמי נדרש': '410,000 ₪' } },
  { name: 'inventory', value: '40000', expect: { 'סך השקעה ראשונית': '610,000 ₪', 'הון עצמי נדרש': '410,000 ₪' } },
  { name: 'reserve', value: '30000', expect: { 'סך השקעה ראשונית': '610,000 ₪', 'הון עצמי נדרש': '410,000 ₪' } },
  { name: 'loanAmount', value: '210000', expect: { 'סך השקעה ראשונית': '600,000 ₪', 'הון עצמי נדרש': '390,000 ₪' } },
  { name: 'monthlyProfit', value: '41000', expect: { 'מס חודשי משוער': '5,980 ₪', 'רווח חודשי לאחר מס': '20,020 ₪', 'תזרים חודשי משוער': '15,020 ₪' } },
  { name: 'ownerSalary', value: '16000', expect: { 'מס חודשי משוער': '5,520 ₪', 'רווח חודשי לאחר מס': '18,480 ₪', 'תזרים חודשי משוער': '13,480 ₪' } },
  { name: 'monthlyLoanPayment', value: '6000', expect: { 'מס חודשי משוער': '5,750 ₪', 'תזרים חודשי משוער': '13,250 ₪' } },
];

test.describe('Калькулятор — формулы и крайние случаи', () => {
  for (const tag of DEVICES) {
    test(`Пересчёт при вводе в каждое из 8 полей без кнопки #d45b2a ${tag} @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      await openCalculator(page);
      await fillInputs(page, SET1);
      await expectResult(page, 'תזרים חודשי משוער', '14,250 ₪');

      for (const c of CASES) {
        await test.step(`#calc-${c.name} = ${c.value}`, async () => {
          await fillInputs(page, { [c.name]: c.value });
          for (const [label, value] of Object.entries(c.expect)) await expectResult(page, label, value);
          await fillInputs(page, { [c.name]: SET1[c.name] });
          await expectResult(page, 'תזרים חודשי משוער', '14,250 ₪');
          await expectResult(page, 'סך השקעה ראשונית', '600,000 ₪');
        });
      }
    });
  }
});
